package com.bulletin.app;
import org.junit.Test;
import java.time.*;
import static org.junit.Assert.*;
public class HistoryAggregationTest{
 private final ZoneId zone=ZoneId.of("Europe/Copenhagen");private final long now=Instant.parse("2026-10-31T12:00:00Z").toEpochMilli();
 private Game game(){return new Game(now,zone);}private long at(long day,int hour){return LocalDate.ofEpochDay(day).atTime(hour,0).atZone(zone).toInstant().toEpochMilli();}
 private Game.HistoryEntry event(Game g,long day,int hour,long count){Game.HistoryEntry e=new Game.HistoryEntry(Game.QUEST_HISTORY,"q","Focus",at(day,hour));e.count=count;e.coinsKnown=true;e.coinsDelta=count*10;g.history.add(e);return e;}
 private long count(Game g){long n=0;for(Game.HistoryEntry e:g.history)n+=e.count;return n;}
 @Test public void dailyAggregationStartsStrictlyAfterThreeMonthsAndDoesNotReward(){Game g=game();long cutoff=LocalDate.ofEpochDay(g.day).minusMonths(3).toEpochDay();event(g,cutoff-1,8,1);event(g,cutoff-1,12,2);Game.HistoryEntry recent=event(g,cutoff,8,1);event(g,g.day,8,1);long coins=g.coins;HistoryAggregation.aggregate(g,zone);assertEquals(3,g.history.size());assertTrue(g.history.contains(recent));Game.HistoryEntry old=g.history.get(0);assertEquals(1,old.precision);assertEquals(3,old.count);assertEquals(30,old.coinsDelta);assertTrue(old.coinsKnown);assertEquals(coins,g.coins);assertEquals(0,g.completedToday);}
 @Test public void weeklyAggregationPreservesCountsMoneyAndFocus(){Game g=game();long year=LocalDate.ofEpochDay(g.day).minusYears(1).toEpochDay(),day=HistoryAggregation.week(year-14);event(g,day,9,2);event(g,day+1,13,3);g.focus.add(new Game.FocusEntry("q","Focus",day,60000));g.focus.add(new Game.FocusEntry("q","Focus",day+1,90000));HistoryAggregation.aggregate(g,zone);assertEquals(1,g.history.size());assertEquals(7,g.history.get(0).precision);assertEquals(5,count(g));assertEquals(50,g.history.get(0).coinsDelta);assertEquals(day+6,g.history.get(0).endDay);assertEquals(1,g.focus.size());assertEquals(150000,g.focus.get(0).millis);assertEquals(day+6,g.focus.get(0).endDay);}
 @Test public void aggregationIsIdempotentAndPartialWeeksMergeAsTheyAge()throws Exception{Game g=game();long cutoff=LocalDate.ofEpochDay(g.day).minusYears(1).toEpochDay();event(g,cutoff-1,9,1);event(g,cutoff,13,1);HistoryAggregation.aggregate(g,zone);String saved=GameCodec.encodeLegacy(g).toString();HistoryAggregation.aggregate(g,zone);assertEquals(saved,GameCodec.encodeLegacy(g).toString());g.day+=7;HistoryAggregation.aggregate(g,zone);assertEquals(1,g.history.size());assertEquals(2,count(g));assertEquals(7,g.history.get(0).precision);}
 @Test public void daysUseCalendarBoundariesAcrossDaylightSaving(){Game g=game();long day=LocalDate.of(2026,3,29).toEpochDay();event(g,day,1,1);event(g,day,15,1);HistoryAggregation.aggregate(g,zone);assertEquals(1,g.history.size());assertEquals(day,g.history.get(0).bucketDay);assertEquals(23*3600000L,HistoryAggregation.millis(day+1,zone)-HistoryAggregation.millis(day,zone));}
 @Test public void balanceDailyAndWeeklySummariesKeepOpeningClosingMinimumAndMaximum(){Game g=game();long day=HistoryAggregation.week(g.day-110);g.balances.clear();g.balances.add(new Game.BalancePoint(at(day,1),100,"start"));g.balances.add(new Game.BalancePoint(at(day,10),200,"up"));g.balances.add(new Game.BalancePoint(at(day,20),50,"down"));g.balances.add(new Game.BalancePoint(at(day+1,10),90,"next"));HistoryAggregation.aggregate(g,zone);assertEquals(2,g.balances.size());Game.BalancePoint p=g.balances.get(0);assertEquals(100,p.opening);assertEquals(50,p.cents);assertEquals(50,p.minimum);assertEquals(200,p.maximum);assertEquals(1,p.precision);assertEquals(50,g.balances.get(1).opening);g.day=day+400;HistoryAggregation.aggregate(g,zone);assertEquals(1,g.balances.size());p=g.balances.get(0);assertEquals(7,p.precision);assertEquals(100,p.opening);assertEquals(90,p.cents);assertEquals(50,p.minimum);assertEquals(200,p.maximum);}
 @Test public void currentRecordsUndoAndRunningSessionsRemainUntouched(){Game g=game();Game.Quest q=new Game.Quest();q.name="Task";q.repeatable=true;q.forever=true;q.firstDay=g.day;g.addQuest(q);g.start(q,now);Game.Session session=g.session;Game.UndoEntry undo=new Game.UndoEntry();undo.questId=q.id;undo.at=now;g.undo.add(undo);Game.HistoryEntry recent=event(g,g.day,9,1);Game.BalancePoint point=new Game.BalancePoint(now,123,"Exact cause");g.balances.clear();g.balances.add(point);HistoryAggregation.aggregate(g,zone);assertSame(session,g.session);assertSame(undo,g.undo.get(0));assertSame(recent,g.history.get(0));assertSame(point,g.balances.get(0));}
 @Test public void summarizedBalanceExtremaSurviveCompactAndCompressedReload()throws Exception{Game g=game();long day=g.day-500;g.balances.clear();g.balances.add(new Game.BalancePoint(at(day,1),100,"start"));g.balances.add(new Game.BalancePoint(at(day,2),-700,"down"));g.balances.add(new Game.BalancePoint(at(day,3),900,"up"));HistoryAggregation.aggregate(g,zone);Game loaded=GameCodec.decode(SaveCompression.pack(GameCodec.encode(g).toString()),now,zone);Game.BalancePoint a=g.balances.get(0),b=loaded.balances.get(0);assertEquals(a.periodStart,b.periodStart);assertEquals(a.periodEnd,b.periodEnd);assertEquals(a.opening,b.opening);assertEquals(a.minimum,b.minimum);assertEquals(a.maximum,b.maximum);assertEquals(a.cents,b.cents);assertEquals(a.precision,b.precision);assertEquals(a.cause,b.cause);}
 @Test public void countsBeyondIntegerRangeAndUnknownMoneyRemainSafe()throws Exception{Game g=game();long day=g.day-110;event(g,day,1,2000000000L);Game.HistoryEntry b=event(g,day,2,2000000000L);b.coinsKnown=false;b.coinsDelta=0;HistoryAggregation.aggregate(g,zone);assertEquals(4000000000L,g.history.get(0).count);assertFalse(g.history.get(0).coinsKnown);Game loaded=GameCodec.decode(GameCodec.encode(g).toString(),now,zone);assertEquals(4000000000L,loaded.history.get(0).count);}
}